import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_tall_skinny_f32(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K,
    .param .u32 N
)
{
    .reg .pred p0, p1, p2, pRow, pCol0, pCol1, pCol2, pCol3, pFull, pValidFull, pDo0, pDo1, pDo2, pDo3;
    .reg .b32 rM, rK, rN, ri, rj, rj_base, rk, tmp32, rK4;
    .reg .b32 rtid_x, rtid_y, rctaid_x, rctaid_y, rntid_x, rntid_y;
    .reg .b64 rA, rB, rC, addrA, addrB, addrC, idx64, tmp64a, tmp64b, rk64, rj64, jbase64, sNbytes64;
    .reg .f32 fa, sa, fa0, fa1, fa2, fa3, sa0, sa1, sa2, sa3, fb0, fb1, fb2, fb3, acc0, acc1, acc2, acc3;
    // Load parameters
    ld.param.u64 rA, [A_ptr];
    ld.param.u64 rB, [B_ptr];
    ld.param.u64 rC, [C_ptr];
    ld.param.u32 rM, [M];
    ld.param.u32 rK, [K];
    ld.param.u32 rN, [N];
    // Compute thread coordinates: i (row), j_base (starting column for 4-wide tile)
    mov.u32 rtid_x, %tid.x;
    mov.u32 rtid_y, %tid.y;
    mov.u32 rctaid_x, %ctaid.x;
    mov.u32 rctaid_y, %ctaid.y;
    mov.u32 rntid_x, %ntid.x;
    mov.u32 rntid_y, %ntid.y;
    mad.lo.s32 rj, rctaid_x, rntid_x, rtid_x; // j_thread = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.s32 ri, rctaid_y, rntid_y, rtid_y; // i = blockIdx.y * blockDim.y + threadIdx.y
    shl.b32      rj_base, rj, 2;             // j_base = j_thread * 4
    cvt.u64.u32  jbase64, rj_base;
    // Predicates for bounds
    setp.lt.u32 pRow,  ri, rM;
    add.s32 tmp32, rj_base, 3;
    setp.lt.u32 pFull, tmp32, rN;            // j_base+3 < N
    setp.lt.u32 pCol0, rj_base, rN;
    add.s32 tmp32, rj_base, 1; setp.lt.u32 pCol1, tmp32, rN;
    add.s32 tmp32, rj_base, 2; setp.lt.u32 pCol2, tmp32, rN;
    add.s32 tmp32, rj_base, 3; setp.lt.u32 pCol3, tmp32, rN;
    and.pred    pValidFull, pRow, pFull;
    // Accumulator init
    mov.f32 acc0, 0f00000000;
    mov.f32 acc1, 0f00000000;
    mov.f32 acc2, 0f00000000;
    mov.f32 acc3, 0f00000000;
    // Precompute stride for B between successive rk (N * sizeof(float))
    cvt.u64.u32  sNbytes64, rN;
    shl.b64      sNbytes64, sNbytes64, 2;
    // Lane0 predicate (constant per thread)
    setp.eq.u32 p2, rtid_x, 0;
    // Unrolled K-loop by 4
    mov.u32 rk, 0;
    and.b32 rK4, rK, 0xfffffffc; // rK4 = (K/4)*4
LOOP_K4:
    setp.ge.u32 p1, rk, rK4;
    @p1 bra SCALAR_TAIL;
    // Compute base address for A[i, rk] (lane0 will use it)
    cvt.u64.u32 rk64, rk;
    mad.wide.u32 tmp64a, ri, rK, rk64;   // i*K + rk in 64-bit
    shl.b64      tmp64a, tmp64a, 2;      // *4 bytes
    add.u64      addrA,  rA,     tmp64a;
    // Lane 0 loads 4 consecutive A elements (rk..rk+3) and broadcast
    @!p2 bra SKIP_LANE_LOAD4;
        @pRow bra LOAD_A4;
        mov.f32 fa0, 0f00000000;
        mov.f32 fa1, 0f00000000;
        mov.f32 fa2, 0f00000000;
        mov.f32 fa3, 0f00000000;
        bra AFTER_LANE_LOAD4;
LOAD_A4:
        ld.global.f32 fa0, [addrA];
        add.u64 tmp64b, addrA, 4;  ld.global.f32 fa1, [tmp64b];
        add.u64 tmp64b, addrA, 8;  ld.global.f32 fa2, [tmp64b];
        add.u64 tmp64b, addrA, 12; ld.global.f32 fa3, [tmp64b];
AFTER_LANE_LOAD4:
SKIP_LANE_LOAD4:
    // Broadcast A elements from lane 0 to all threads in the warp
    shfl.sync.idx.b32 sa0, fa0, 0, 0x1f, 0xffffffff;
    shfl.sync.idx.b32 sa1, fa1, 0, 0x1f, 0xffffffff;
    shfl.sync.idx.b32 sa2, fa2, 0, 0x1f, 0xffffffff;
    shfl.sync.idx.b32 sa3, fa3, 0, 0x1f, 0xffffffff;
    // Load B and FMA: vectorized path if full 4-wide tile fits, else scalar tail path
    @pFull bra VEC_PATH4;
    // Tail path (scalar loads) for up to 4 columns with bounds, unrolled over 4 K-steps
    mad.wide.u32 tmp64b, rk, rN, jbase64;   // rk*N + j_base in 64-bit
    shl.b64      tmp64b, tmp64b, 2;         // *4 bytes
    add.u64      addrB,  rB,     tmp64b;
    // u = 0
    and.pred    pDo0, pCol0, pRow;
    and.pred    pDo1, pCol1, pRow;
    and.pred    pDo2, pCol2, pRow;
    and.pred    pDo3, pCol3, pRow;
    @pCol0 ld.global.f32 fb0, [addrB];
    @pDo0  fma.rn.f32   acc0, sa0, fb0, acc0;
    @pCol1 add.u64 tmp64a, addrB, 4;
    @pCol1 ld.global.f32 fb1, [tmp64a];
    @pDo1  fma.rn.f32   acc1, sa0, fb1, acc1;
    @pCol2 add.u64 tmp64a, addrB, 8;
    @pCol2 ld.global.f32 fb2, [tmp64a];
    @pDo2  fma.rn.f32   acc2, sa0, fb2, acc2;
    @pCol3 add.u64 tmp64a, addrB, 12;
    @pCol3 ld.global.f32 fb3, [tmp64a];
    @pDo3  fma.rn.f32   acc3, sa0, fb3, acc3;
    // u = 1
    add.u64 addrB, addrB, sNbytes64;
    @pCol0 ld.global.f32 fb0, [addrB];
    @pDo0  fma.rn.f32   acc0, sa1, fb0, acc0;
    @pCol1 add.u64 tmp64a, addrB, 4;
    @pCol1 ld.global.f32 fb1, [tmp64a];
    @pDo1  fma.rn.f32   acc1, sa1, fb1, acc1;
    @pCol2 add.u64 tmp64a, addrB, 8;
    @pCol2 ld.global.f32 fb2, [tmp64a];
    @pDo2  fma.rn.f32   acc2, sa1, fb2, acc2;
    @pCol3 add.u64 tmp64a, addrB, 12;
    @pCol3 ld.global.f32 fb3, [tmp64a];
    @pDo3  fma.rn.f32   acc3, sa1, fb3, acc3;
    // u = 2
    add.u64 addrB, addrB, sNbytes64;
    @pCol0 ld.global.f32 fb0, [addrB];
    @pDo0  fma.rn.f32   acc0, sa2, fb0, acc0;
    @pCol1 add.u64 tmp64a, addrB, 4;
    @pCol1 ld.global.f32 fb1, [tmp64a];
    @pDo1  fma.rn.f32   acc1, sa2, fb1, acc1;
    @pCol2 add.u64 tmp64a, addrB, 8;
    @pCol2 ld.global.f32 fb2, [tmp64a];
    @pDo2  fma.rn.f32   acc2, sa2, fb2, acc2;
    @pCol3 add.u64 tmp64a, addrB, 12;
    @pCol3 ld.global.f32 fb3, [tmp64a];
    @pDo3  fma.rn.f32   acc3, sa2, fb3, acc3;
    // u = 3
    add.u64 addrB, addrB, sNbytes64;
    @pCol0 ld.global.f32 fb0, [addrB];
    @pDo0  fma.rn.f32   acc0, sa3, fb0, acc0;
    @pCol1 add.u64 tmp64a, addrB, 4;
    @pCol1 ld.global.f32 fb1, [tmp64a];
    @pDo1  fma.rn.f32   acc1, sa3, fb1, acc1;
    @pCol2 add.u64 tmp64a, addrB, 8;
    @pCol2 ld.global.f32 fb2, [tmp64a];
    @pDo2  fma.rn.f32   acc2, sa3, fb2, acc2;
    @pCol3 add.u64 tmp64a, addrB, 12;
    @pCol3 ld.global.f32 fb3, [tmp64a];
    @pDo3  fma.rn.f32   acc3, sa3, fb3, acc3;
    bra CONT_K4;
VEC_PATH4:
    // Vectorized path, unrolled over 4 K-steps
    mad.wide.u32 tmp64b, rk, rN, jbase64;   // rk*N + j_base in 64-bit
    shl.b64      tmp64b, tmp64b, 2;         // *4 bytes
    add.u64      addrB,  rB,     tmp64b;
    // u = 0
    ld.global.v4.f32 {fb0, fb1, fb2, fb3}, [addrB];
    @pRow fma.rn.f32   acc0, sa0, fb0, acc0;
    @pRow fma.rn.f32   acc1, sa0, fb1, acc1;
    @pRow fma.rn.f32   acc2, sa0, fb2, acc2;
    @pRow fma.rn.f32   acc3, sa0, fb3, acc3;
    // u = 1
    add.u64      addrB, addrB, sNbytes64;
    ld.global.v4.f32 {fb0, fb1, fb2, fb3}, [addrB];
    @pRow fma.rn.f32   acc0, sa1, fb0, acc0;
    @pRow fma.rn.f32   acc1, sa1, fb1, acc1;
    @pRow fma.rn.f32   acc2, sa1, fb2, acc2;
    @pRow fma.rn.f32   acc3, sa1, fb3, acc3;
    // u = 2
    add.u64      addrB, addrB, sNbytes64;
    ld.global.v4.f32 {fb0, fb1, fb2, fb3}, [addrB];
    @pRow fma.rn.f32   acc0, sa2, fb0, acc0;
    @pRow fma.rn.f32   acc1, sa2, fb1, acc1;
    @pRow fma.rn.f32   acc2, sa2, fb2, acc2;
    @pRow fma.rn.f32   acc3, sa2, fb3, acc3;
    // u = 3
    add.u64      addrB, addrB, sNbytes64;
    ld.global.v4.f32 {fb0, fb1, fb2, fb3}, [addrB];
    @pRow fma.rn.f32   acc0, sa3, fb0, acc0;
    @pRow fma.rn.f32   acc1, sa3, fb1, acc1;
    @pRow fma.rn.f32   acc2, sa3, fb2, acc2;
    @pRow fma.rn.f32   acc3, sa3, fb3, acc3;
CONT_K4:
    add.s32 rk, rk, 4;
    bra LOOP_K4;
SCALAR_TAIL:
    // Scalar tail loop for remaining K (0..3 iterations)
LOOP_TAIL:
    setp.ge.u32 p1, rk, rK;
    @p1 bra STORE;
    // Lane 0 of each warp loads A[i, rk], broadcast via shuffle
    @!p2 bra SKIP_LANE_LOAD_TAIL;
        @pRow bra LOAD_A_TAIL;
        // Row out of bounds: use zero
        mov.f32 fa, 0f00000000;
        bra AFTER_LANE_LOAD_TAIL;
LOAD_A_TAIL:
        cvt.u64.u32 rk64, rk;
        mad.wide.u32 tmp64a, ri, rK, rk64;   // i*K + rk in 64-bit
        shl.b64      tmp64a, tmp64a, 2;      // *4 bytes
        add.u64      addrA,  rA,     tmp64a;
        ld.global.f32 fa, [addrA];
AFTER_LANE_LOAD_TAIL:
SKIP_LANE_LOAD_TAIL:
    // Broadcast A element from lane 0 to all threads in the warp
    shfl.sync.idx.b32 sa, fa, 0, 0x1f, 0xffffffff;
    // Load B and FMA: vectorized path if full 4-wide tile fits, else scalar tail path
    @pFull bra VEC_PATH_TAIL;
    // Tail path: handle up to 4 columns with bounds
    mad.wide.u32 tmp64b, rk, rN, jbase64;   // rk*N + j_base in 64-bit
    shl.b64      tmp64b, tmp64b, 2;         // *4 bytes
    add.u64      addrB,  rB,     tmp64b;
    and.pred    pDo0, pCol0, pRow;
    and.pred    pDo1, pCol1, pRow;
    and.pred    pDo2, pCol2, pRow;
    and.pred    pDo3, pCol3, pRow;
    @pCol0 ld.global.f32 fb0, [addrB];
    @pDo0  fma.rn.f32   acc0, sa, fb0, acc0;
    @pCol1 add.u64 tmp64a, addrB, 4;
    @pCol1 ld.global.f32 fb1, [tmp64a];
    @pDo1  fma.rn.f32   acc1, sa, fb1, acc1;
    @pCol2 add.u64 tmp64a, addrB, 8;
    @pCol2 ld.global.f32 fb2, [tmp64a];
    @pDo2  fma.rn.f32   acc2, sa, fb2, acc2;
    @pCol3 add.u64 tmp64a, addrB, 12;
    @pCol3 ld.global.f32 fb3, [tmp64a];
    @pDo3  fma.rn.f32   acc3, sa, fb3, acc3;
    bra CONT_TAIL;
VEC_PATH_TAIL:
    mad.wide.u32 tmp64b, rk, rN, jbase64;   // rk*N + j_base in 64-bit
    shl.b64      tmp64b, tmp64b, 2;         // *4 bytes
    add.u64      addrB,  rB,     tmp64b;
    ld.global.v4.f32 {fb0, fb1, fb2, fb3}, [addrB];
    @pRow fma.rn.f32   acc0, sa, fb0, acc0;
    @pRow fma.rn.f32   acc1, sa, fb1, acc1;
    @pRow fma.rn.f32   acc2, sa, fb2, acc2;
    @pRow fma.rn.f32   acc3, sa, fb3, acc3;
CONT_TAIL:
    add.s32 rk, rk, 1;
    bra LOOP_TAIL;
STORE:
    // Store C: vector store if full 4-wide tile and row valid, else scalar tail stores
    @pValidFull bra STORE_VEC;
    @!pRow bra DONE;
    mad.wide.u32 idx64,  ri, rN, jbase64;   // i*N + j_base in 64-bit
    shl.b64      idx64,  idx64,  2;         // *4 bytes
    add.u64      addrC,  rC,     idx64;
    @pCol0 st.global.f32 [addrC], acc0;
    @pCol1 add.u64 tmp64a, addrC, 4;
    @pCol1 st.global.f32 [tmp64a], acc1;
    @pCol2 add.u64 tmp64a, addrC, 8;
    @pCol2 st.global.f32 [tmp64a], acc2;
    @pCol3 add.u64 tmp64a, addrC, 12;
    @pCol3 st.global.f32 [tmp64a], acc3;
    bra DONE;
STORE_VEC:
    mad.wide.u32 idx64,  ri, rN, jbase64;   // i*N + j_base in 64-bit
    shl.b64      idx64,  idx64,  2;         // *4 bytes
    add.u64      addrC,  rC,     idx64;
    st.global.v4.f32 [addrC], {acc0, acc1, acc2, acc3};
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_tall_skinny_f32")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        if not (isinstance(A, torch.Tensor) and isinstance(B, torch.Tensor)):
            raise TypeError("Inputs must be torch.Tensors")
        if A.dim() != 2 or B.dim() != 2:
            raise ValueError("A and B must be 2D tensors")
        if A.shape[1] != B.shape[0]:
            raise ValueError("Incompatible shapes for matmul: A(M,K) and B(K,N) required")
        if A.dtype != torch.float32 or B.dtype != torch.float32:
            raise NotImplementedError("This kernel supports only float32 tensors")
        if A.device.type != "cuda" or B.device.type != "cuda":
            raise NotImplementedError("This kernel requires CUDA tensors")
        if A.device != B.device:
            raise ValueError("A and B must be on the same device")
        if not A.is_contiguous() or not B.is_contiguous():
            raise NotImplementedError("This kernel requires contiguous inputs")

        M = int(A.shape[0])
        K = int(A.shape[1])
        N = int(B.shape[1])

        C = torch.empty((M, N), device=A.device, dtype=A.dtype)

        if M == 0 or N == 0 or K == 0:
            return C

        block_x, block_y, block_z = 32, 8, 1
        grid_x = (N + (4 * block_x) - 1) // (4 * block_x)
        grid_y = (M + block_y - 1) // block_y
        grid_z = 1

        module = _get_ptx_module()
        module.launch(
            "matmul_tall_skinny_f32",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[A, B, C, u32(M), u32(K), u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

