    mov.f32 acc0, 0f00000000;
    mov.f32 acc1, 0f00000000;
    mov.f32 acc2, 0f00000000;
    mov.f32 acc3, 0f00000000;
    mov.u32 rk, 0;
LOOP_K:
    setp.ge.u32 p1, rk, rK;
    @p1 bra STORE;
    // Lane 0 of each warp loads A[i, rk], broadcast via shuffle
    setp.eq.u32 p2, rtid_x, 0;
    @!p2 bra SKIP_LANE_LOAD;
        @pRow bra LOAD_A;
        // Row out of bounds: use zero
        mov.f32 fa, 0f00000000;
        bra AFTER_LANE_LOAD;
LOAD_A:
        cvt.u64.u32 rk64, rk;
        mad.wide.u32 tmp64a, ri, rK, rk64;   // i*K + rk in 64-bit
        shl.b64      tmp64a, tmp64a, 2;      // *4 bytes
        add.u64      addrA,  rA,     tmp64a;
        ld.global.f32 fa, [addrA];
AFTER_LANE_LOAD:
SKIP_LANE_LOAD:
